  title = 'Production Practicum / Ensemble',
  goal = 'Production Practicum / Ensemble',
  summary = 'A hands-on production laboratory in ensemble theater practice. Students participate in department productions through rotating performance, crew, management, and technical roles while learning rehearsal etiquette, production communication, safety practice, tech-week discipline, show running, strike, and reflective evaluation.',
